test("casts over an instance of Item", () => {
  const theItem =
    TestCommonJsonization.loadMinimalItem();

  expect(
    AasTypes.isItem(theItem)
  ).toStrictEqual(true);
  expect(
    AasTypes.asItem(theItem)
  ).toStrictEqual(theItem);

  expect(
    AasTypes.isParent(theItem)
  ).toStrictEqual(false);
  expect(
    AasTypes.asParent(theItem)
  ).toBeNull();

  expect(
    AasTypes.isChildA(theItem)
  ).toStrictEqual(false);
  expect(
    AasTypes.asChildA(theItem)
  ).toBeNull();

  expect(
    AasTypes.isChildB(theItem)
  ).toStrictEqual(false);
  expect(
    AasTypes.asChildB(theItem)
  ).toBeNull();

  expect(
    AasTypes.isSomething(theItem)
  ).toStrictEqual(false);
  expect(
    AasTypes.asSomething(theItem)
  ).toBeNull();
});

